import { useVendorOrdersQuery } from '../../store/api/vendorApi';
export default function VendorOrders(){const{data,isLoading}=useVendorOrdersQuery();const orders=data?.orders||[];return <main className="mx-auto max-w-7xl px-4 py-10"><h1 className="font-heading text-5xl text-navy">Vendor Orders</h1><div className="mt-6 flex gap-2">{['confirmed','processing','dispatched','delivered'].map(s=><button className="rounded border px-4 py-2 text-navy" key={s}>{s}</button>)}</div><div className="card mt-6 overflow-x-auto p-5">{isLoading?<p>Loading...</p>:!orders.length?<p>No vendor orders.</p>:<table className="w-full text-left"><thead><tr><th>Order</th><th>Customer</th><th>Amount</th><th>Status</th><th>Action</th></tr></thead><tbody>{orders.map(o=><tr className="border-t" key={o._id}><td>{o.orderNumber}</td><td>{o.shippingAddress?.name}</td><td>₹{o.totalAmount}</td><td><select className="input"><option>{o.orderStatus}</option><option>processing</option><option>dispatched</option></select></td><td><button className="btn-navy">Mark Dispatched</button></td></tr>)}</tbody></table>}</div></main>}
